shaderSource:
uniform float2 resolution;
uniform float time;

float hash(float2 p) {
  return fract(sin(dot(p, float2(12.9898, 78.233))) * 43758.5453);
}

float valueNoise(float2 p) {
  float2 i = floor(p);
  float2 f = fract(p);
  float2 u = f * f * (3.0 - 2.0 * f);
  float a = hash(i);
  float b = hash(i + float2(1.0, 0.0));
  float c = hash(i + float2(0.0, 1.0));
  float d = hash(i + float2(1.0, 1.0));
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

float turbulence(float2 p) {
  float v = 0.0;
  v += valueNoise(p) * 0.5;
  v += valueNoise(p * 2.03) * 0.25;
  v += valueNoise(p * 4.07) * 0.125;
  v += valueNoise(p * 8.13) * 0.0625;
  return v;
}

half4 main(float2 xy) {
  float2 uv = xy / max(resolution, float2(1.0, 1.0));
  float aspect = resolution.x / max(resolution.y, 1.0);

  // y=0 top in UV — flip so fire rises from the bottom of the button
  float yUp = 1.0 - uv.y;

  // Wide base, taper as flames climb
  float taper = 0.55 + yUp * 0.55;
  float cx = abs(uv.x - 0.5) * aspect;

  // Scroll noise UPWARD (negative y over time)
  float2 np = float2(uv.x * aspect * 4.2, yUp * 7.5 - time * 2.8);
  float n = turbulence(np);
  n += 0.45 * turbulence(np * 1.85 + float2(time * 0.35, -time * 1.4));
  n += 0.2 * turbulence(np * 3.1 + float2(-time * 0.6, time * 0.9));

  float pillar = 1.0 - smoothstep(taper * 0.35, taper, cx + (n - 0.5) * 0.28);

  // Bigger fire: strong near base, still visible mid-button, soft tips near top
  float heightFade = pow(clamp(1.0 - yUp * 0.72, 0.0, 1.0), 0.55);
  float intensity = clamp(n * 1.85 * heightFade * pillar, 0.0, 1.35);
  intensity += (1.0 - smoothstep(0.0, 0.28, yUp)) * pillar * 0.35;

  // Charcoal body under the flames
  half3 body = mix(half3(0.05, 0.02, 0.01), half3(0.12, 0.04, 0.015), uv.y);

  half3 fire = half3(0.0, 0.0, 0.0);
  fire = mix(fire, half3(0.5, 0.02, 0.0), smoothstep(0.05, 0.22, intensity));
  fire = mix(fire, half3(1.0, 0.22, 0.0), smoothstep(0.22, 0.42, intensity));
  fire = mix(fire, half3(1.0, 0.55, 0.05), smoothstep(0.42, 0.62, intensity));
  fire = mix(fire, half3(1.0, 0.88, 0.28), smoothstep(0.62, 0.82, intensity));
  fire = mix(fire, half3(1.0, 0.98, 0.88), smoothstep(0.82, 1.15, intensity));

  half3 col = body + fire * intensity;

  // Rising tips — bright streaks that climb
  float tips = pillar * smoothstep(0.4, 0.9, n) * smoothstep(0.15, 0.75, yUp);
  col += half3(1.0, 0.95, 0.7) * tips * 0.45;

  // Ember glow across the lower half
  float baseGlow = pillar * (1.0 - smoothstep(0.0, 0.55, yUp));
  col += half3(1.0, 0.35, 0.02) * baseGlow * 0.28;

  float alpha = mix(0.95, 1.0, clamp(intensity, 0.0, 1.0));
  return half4(col, alpha);
}
